package com.digitaloffice.work;
import jakarta.persistence.*; import java.time.Instant; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="tasks",indexes=@Index(name="ix_tasks_project_status",columnList="project_id,status"))
public class Task {
 @Id private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(nullable=false) private String title; private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private TaskStatus status; private String priority; private UUID assigneeId; private LocalDate dueDate; @Column(nullable=false) private UUID createdBy; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @Version private long version;
 protected Task(){} public Task(UUID p,String t,String d,String pr,LocalDate due,UUID actor){id=UUID.randomUUID();projectId=p;title=t;description=d;priority=pr;dueDate=due;createdBy=actor;status=TaskStatus.TODO;createdAt=Instant.now();updatedAt=createdAt;}
 public UUID getId(){return id;} public UUID getProjectId(){return projectId;} public UUID getCreatedBy(){return createdBy;} public String getTitle(){return title;} public String getDescription(){return description;} public TaskStatus getStatus(){return status;} public String getPriority(){return priority;} public UUID getAssigneeId(){return assigneeId;} public LocalDate getDueDate(){return dueDate;}
 public void update(String t,String d,String p,LocalDate due){title=t;description=d;priority=p;dueDate=due;updatedAt=Instant.now();} public void assign(UUID id){assigneeId=id;updatedAt=Instant.now();} public void transition(TaskStatus next){if(status==TaskStatus.TODO&&next!=TaskStatus.IN_PROGRESS&&next!=TaskStatus.CANCELLED||status==TaskStatus.IN_PROGRESS&&next!=TaskStatus.BLOCKED&&next!=TaskStatus.DONE&&next!=TaskStatus.TODO||status==TaskStatus.BLOCKED&&next!=TaskStatus.IN_PROGRESS||status==TaskStatus.DONE&&next!=TaskStatus.IN_PROGRESS)throw new IllegalArgumentException("Invalid task transition");status=next;updatedAt=Instant.now();}
}
